CREATE COLUMN TABLE "TEST_AP"."ITM1" ("ItemCode" NVARCHAR(50) NOT NULL , "PriceList" SMALLINT CS_INT NOT NULL , "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Ovrwritten" NVARCHAR(1) DEFAULT 'N', "Factor" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjType" NVARCHAR(20) DEFAULT '4', "AddPrice1" DECIMAL(21,6) CS_FIXED, "Currency1" NVARCHAR(3), "AddPrice2" DECIMAL(21,6) CS_FIXED, "Currency2" NVARCHAR(3), "Ovrwrite1" NVARCHAR(1) DEFAULT 'N', "Ovrwrite2" NVARCHAR(1) DEFAULT 'N', "BasePLNum" SMALLINT CS_INT, "UomEntry" INTEGER CS_INT, "PriceType" NVARCHAR(1) DEFAULT 'M', PRIMARY KEY ("ItemCode", "PriceList")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "ITM1_CURRENCY" ON "TEST_AP"."ITM1" ( "Currency" ASC );
CREATE INDEX "ITM1_PRICE_LIST" ON "TEST_AP"."ITM1" ( "PriceList" ASC );
CREATE INDEX "ITM1_MANUAL" ON "TEST_AP"."ITM1" ( "Ovrwritten" ASC )